def transform(grid):
    from math import gcd
    from functools import reduce

    h, w = len(grid), len(grid[0])
    cells8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells8:
        return [row[:] for row in grid]

    # The repeating square tile size is the gcd of the contiguous 8-runs.
    runs = []
    for r in range(h):
        n = 0
        for c in range(w):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
    for c in range(w):
        n = 0
        for r in range(h):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
    tile = reduce(gcd, runs)

    colored = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    r0 = min(r for r, c, v in colored)
    r1 = max(r for r, c, v in colored)
    c0 = min(c for r, c, v in colored)
    c1 = max(c for r, c, v in colored)
    motif = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r, c, v in colored:
        motif[r - r0][c - c0] = v

    # Rotate the small color pattern clockwise.
    rotated = [list(row) for row in zip(*motif[::-1])]

    out = [row[:] for row in grid]
    ar = min(r for r, c in cells8)
    ac = min(c for r, c in cells8)
    for r in range(ar, h, tile):
        for c in range(ac, w, tile):
            if not any(grid[i][j] == 8
                       for i in range(r, min(r + tile, h))
                       for j in range(c, min(c + tile, w))):
                continue
            mr = (r - ar) // tile
            mc = (c - ac) // tile
            if mr < len(rotated) and mc < len(rotated[0]) and rotated[mr][mc]:
                color = rotated[mr][mc]
                for i in range(r, min(r + tile, h)):
                    for j in range(c, min(c + tile, w)):
                        if grid[i][j] == 8:
                            out[i][j] = color
    return out
